// === Tab: mySketch ===
let cols, rows;
let flowField;
let particles = [];
let vortexes = [];

function setup() {
  createCanvas(400, 400);
  cols = width / 20;
  rows = height / 20;

  flowField = createFlowField(cols, rows);

  // Create particles
  for (let i = 0; i < 10000; i++) {
    particles.push(new Particle());
  }
}

function draw() {
  background(220);

  particles.push(new Particle());
  // Update and display particles
  for (let particle of particles) {
    particle.follow(flowField);
    particle.update();
    particle.display();
  }

  displayFlowField(flowField);

  vortexes.forEach(vortex => {
     if (vortex) {
      vortex.update();
      vortex.display();
    }
  })
}

function mouseClicked() {
vortexes.push(new Vortex((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))));
}

function createFlowField(cols, rows) {
  let field = [];
  let inc = 0.1;
  let start = 0;

  for (let i = 0; i < cols; i++) {
    field[i] = [];
    for (let j = 0; j < rows; j++) {
      let x = i * inc + start;
      let y = j * inc + start;
      let angle = noise(x, y) * TWO_PI * 4; // Adjust the multiplier to control the flow

      let v = p5.Vector.fromAngle(angle);
      field[i][j] = v;
    }
  }

  return field;
}

function displayFlowField(field) {
  let scale = 20;

  for (let i = 0; i < cols; i++) {
    for (let j = 0; j < rows; j++) {
      var x = i * scale;
      var y = j * scale;

      push();
      translate(x, y);
      rotate(field[i][j].heading());
      stroke(0, 50);
      strokeWeight(1);
      line(0, 0, scale, 0);
      pop();
    }
  }
}

class Particle {
  constructor() {
    this.position = createVector(random(width), random(height));
    this.velocity = createVector();
    this.acceleration = createVector();
    this.maxSpeed = 2;
    this.radius = 2;
  }

  follow(field) {
    var x = floor(this.position.x / 20);
    var y = floor(this.position.y / 20);

    // Check if particle is within the bounds of the flow field
    if (x >= 0 && x < cols && y >= 0 && y < rows) {
      let force = field[x][y].copy();

      for (let vortex of vortexes) {
        if (this.position.dist(vortex.position) < vortex.radius) {
          let vortexForce = p5.Vector.sub(this.position, vortex.position);
          vortexForce.rotate(Math.PI/2)
          vortexForce.normalize().mult(15)
          force.add(vortexForce);
        }
      }
      this.applyForce(force);
    }


  }

  applyForce(force) {
    this.acceleration.add(force);
  }

  update() {
    this.velocity.add(this.acceleration);
    this.velocity.limit(this.maxSpeed);
    this.position.add(this.velocity);
    this.acceleration.mult(0);

    // Wrap around the edges
    if (this.position.x < 0) this.position.x = width;
    if (this.position.x > width) this.position.x = 0;
    if (this.position.y < 0) this.position.y = height;
    if (this.position.y > height) this.position.y = 0;
  }

  display() {
    fill(0);
    noStroke();
    ellipse(this.position.x, this.position.y, this.radius * 2, this.radius * 2);
  }
}

class Vortex {
  constructor(x, y) {
    this.position = createVector(x, y);
    this.radius = 50;
    this.strength = 0.05;
  }

  update() {
  }

  display() {
    fill(255, 0, 0, 10);
    noStroke();
    ellipse(this.position.x, this.position.y, this.radius * 2, this.radius * 2);
  }
}

